def set_left_most_unset_bit(n: int) -> int:
    if n <= 0:
        # for 0 the leftmost unset bit is the first bit
        return 1 if n == 0 else n
    bit_len = n.bit_length()
    # scan from the most significant bit downwards
    for i in range(bit_len - 1, -1, -1):
        if ((n >> i) & 1) == 0:
