class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k > n or k <= 0:
            return -1

        cnt = {}
        # all subarrays of size k
        for i in range(n - k + 1):
            window_set = set(nums[i:i + k])
            for v in window_set:
                cnt[v] = cnt.get(v, 0) + 1

        best = -1
        for v, c in cnt.items():
            if c == 1 and v > best:
                best = v
        return best
```

