def is_samepatterns(seq, pattern):
    """Return True if seq and pattern have the same equality pattern.
    The mapping must be bijective: a -> p and p -> a are consistent."""
    if len(seq) != len(pattern):
        return False
    if not seq:  # empty case
        return True

    map_seq_to_pat = {}
    map_pat_to_seq = {}

    for s, p in zip(seq, pattern):
        # seq -> pattern
        if s in map_seq_to_pat:
            if map_seq_to_pat[s] != p:
                return False
        else:
            map_seq_to_pat[s] = p

