def is_simple_power(x, n):
    """Return True if x is a power of n, i.e. x == n**k for some integer k >= 0."""
    # degenerate bases
    if n == 1:
        return x == 1
    if x == 1:
        return True
    if n <= 0 or x <= 0:
        return False

    while x % n == 0:
        x //= n
    return x == 1
