class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        n, m = len(s), len(t)

        # all substrings of s, including empty
        subs_s = []
        for i in range(n + 1):
            for j in range(i, n + 1):
                subs_s.append(s[i:j])

        # all substrings of t, including empty
        subs_t = []
        for i in range(m + 1):
            for j in range(i, m + 1):
                subs_t.append(t[i:j])

        best = 0
        for a in subs_s:
            la = len(a)
            # small pruning
            for b in subs_t:
                total = la + len(b)
                if total <= best:
                    continue
                c = a + b
                if c == c[::-1]:
                    best = total
        return best
```

