from typing import List

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        if not grid or not grid[0]:
            return []
        rows = len(grid)
        cols = len(grid[0])

        seq = []
        for i in range(rows):
            if i % 2 == 0:
                # left to right
                for j in range(cols):
                    seq.append(grid[i][j])
            else:
                # right to left
                for j in range(cols - 1, -1, -1):
                    seq.append(grid[i][j])

        # keep every alternate cell, starting with the first
        res = [seq[k] for k in range(0, len(seq), 2)]
        return res
```

