The offline periods are handled by keeping for each user the time until which they stay offline. All events are sorted by timestamp, with offline starts processed before messages at the same moment. Before handling an event we advance every user whose offline interval has expired, which guarantees the correct online status for `HERE` messages. Messages of type `ALL` increment every user, `HERE` increments only online users, and `idk` mentions increase the specific user regardless of its state. Because the constraints are tiny, a direct scan is sufficient.

```python
class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        offline_until = [None] * numberOfUsers  # None means online

        parsed = []
        for ev in events:
            typ = ev[0]
            ts = int(ev[1])
            payload = ev[2]
            if typ == "OFFLINE":
                user = int(payload)
                parsed.append((ts, 0, "offline", user))
            else:  # MESSAGE
                parsed.append((ts, 1, "message", payload))

        parsed.sort(key=lambda x: (x[0], x[1]))

        for ts, _, kind, data in parsed:
            # expire users whose offline interval ended <= ts
            for u in range(numberOfUsers):
                if offline_until[u] is not None and offline_until[u] <= ts:
                    offline_until[u] = None

            if kind == "offline":
                user = data
                offline_until[user] = ts + 60
            else:  # message
                tokens = data.split()
                for tok in tokens:
                    if tok == "ALL":
                        for u in range(numberOfUsers):
                            mentions[u] += 1
                    elif tok == "HERE":
                        for u in range(numberOfUsers):
                            if offline_until[u] is None:
                                mentions[u] += 1
                    elif tok.startswith("id"):
                        # token like id<number>
                        try:
                            uid = int(tok[2:])
                        except ValueError:
                            continue
                        if 0 <= uid < numberOfUsers:
                            mentions[uid] += 1
                    # unknown tokens are ignored
        return mentions
```

