The robot moves only right or down, so the best profit for each cell depends only on its two predecessors. Keeping three layers for the number of neutralisations used (0, 1 or 2) is enough to decide whether the current negative cell is neutralised or paid for. For a non-negative cell the value is simply added, for a negative cell we can either keep the penalty or replace it by zero while spending one neutralisation. The table is filled in row-major order and the answer is the best value among the three layers at the target cell.

```python
from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m = len(coins)
        n = len(coins[0])
        NEG = -10**18
        dp = [[[NEG] * 3 for _ in range(n)] for __ in range(m)]

        start = coins[0][0]
        if start >= 0:
            dp[0][0][0] = start
            dp[0][0][1] = start
            dp[0][0][2] = start
        else:
            dp[0][0][0] = start
            dp[0][0][1] = 0
            dp[0][0][2] = 0

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                val = coins[i][j]
                for k in range(3):
                    best_prev = NEG
                    if i > 0 and dp[i-1][j][k] != NEG:
                        best_prev = max(best_prev, dp[i-1][j][k])
                    if j > 0 and dp[i][j-1][k] != NEG:
                        best_prev = max(best_prev, dp[i][j-1][k])
                    if best_prev == NEG:
                        continue
                    if val >= 0:
                        dp[i][j][k] = best_prev + val
                    else:
                        # without neutralising
                        opt1 = best_prev + val
                        opt2 = NEG
                        if k > 0:
                            best_prev_neu = NEG
                            if i > 0 and dp[i-1][j][k-1] != NEG:
                                best_prev_neu = max(best_prev_neu, dp[i-1][j][k-1])
                            if j > 0 and dp[i][j-1][k-1] != NEG:
                                best_prev_neu = max(best_prev_neu, dp[i][j-1][k-1])
                            if best_prev_neu != NEG:
                                opt2 = best_prev_neu  # +0
                        dp[i][j][k] = opt1 if opt2 == NEG else (opt1 if opt1 > opt2 else opt2)
        return max(dp[m-1][n-1][k] for k in range(3))
```

