The smallest index for each distinct element value is enough, because only the first occurrence can ever be optimal. With those first indices we can scan the groups by increasing index and mark every multiple of a value that is still unassigned. Once a group receives an assignment it keeps the smallest index seen so far, which is guaranteed by the processing order. The total work is bounded by the harmonic series over the maximal group value.

```python
from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        if not groups:
            return []
        if not elements:
            return [-1] * len(groups)

        # first occurrence of each value
        first_idx = {}
        for j, v in enumerate(elements):
            if v not in first_idx:
                first_idx[v] = j

        max_g = max(groups)
        # -1 means not assigned yet
        best = [-1] * (max_g + 1)

        # process values in order of increasing index
        items = sorted(first_idx.items(), key=lambda x: x[1])  # (value, idx)
        for v, idx in items:
            if v > max_g or v <= 0:
                continue
            # assign to all multiples
            # range is fast enough for max_g <= 1e5
            for m in range(v, max_g + 1, v):
                if best[m] == -1:
                    best[m] = idx
            # optional early stop: if all groups are filled we could break
        return [best[g] for g in groups]
```

